def sem(rs1, rs2, state):
    def s32(x):
        x &= 0xFFFFFFFF
        return x - 0x100000000 if x & 0x80000000 else x
    acc = s32(rs1)
    sh = rs2 & 31
    if sh == 0:
        v = acc
    else:
        v = (acc + (1 << (sh - 1))) >> sh
    if v > 127:
        v = 127
    if v < -128:
        v = -128
    return v & 0xFFFFFFFF, state

def sem(rs1, rs2, state):
    def s8(b):
        return b - 256 if b & 0x80 else b
    out = 0
    for i in range(4):
        a = s8((rs1 >> (8 * i)) & 0xFF)
        b = s8((rs2 >> (8 * i)) & 0xFF)
        m = a if a > b else b
        out |= (m & 0xFF) << (8 * i)
    return out & 0xFFFFFFFF, state
